(()=>{
'use strict';
const en=()=>document.documentElement.lang==='en',t=(he,eng)=>en()?eng:he;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const original=v=>window.GmachOriginalName(v);
async function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',method:opt.method||'GET',headers:{'Content-Type':'application/json'},...(opt.body===undefined?{}:{body:JSON.stringify(opt.body)})}),x=await r.json();if(!r.ok)throw new Error(x.error||t('הפעולה נכשלה','Action failed'));return x}
const days=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'],englishDays=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
function hoursFields(value){let hours={};try{hours=JSON.parse(value||'{}')}catch{}return '<fieldset class="wide"><legend>'+t('שעות פעילות (ללא שעות: בתיאום מראש)','Opening hours (leave blank: by appointment)')+'</legend>'+days.map((day,i)=>{const match=String(hours[day]||'').match(/^(\d{2}:\d{2})[–-](\d{2}:\d{2})$/);return '<label>'+t(day,englishDays[i])+' <input type="time" name="hoursStart'+i+'" value="'+esc(match?.[1]||'')+'"> <input type="time" name="hoursEnd'+i+'" value="'+esc(match?.[2]||'')+'"></label>'}).join('')+'</fieldset>'}
const stateLabel=r=>[({approved:t('מאושר','Approved'),pending:t('ממתין','Pending'),rejected:t('נדחה','Rejected')})[r.status]||r.status,r.is_hidden?t('מוסתר','Hidden'):t('מוצג','Visible'),r.temporarily_closed?t('סגור זמנית','Temporarily closed'):t('פתוח','Open')].join(' · ');
function summary(r){return '<article class="dashboard-row"><div><h3>'+original(r.name)+'</h3><p>'+t('מספר גמ״ח','Gmach number')+': '+esc(r.gmach_code??t('טרם הוקצה','Not assigned'))+' · '+original(r.owner_name||'')+' · '+esc(r.owner_email||'')+'</p><p>'+esc([r.city,r.neighborhood,r.address].filter(Boolean).join(' · '))+'</p><p>'+esc(stateLabel(r))+'</p><small>'+Number(r.item_count||0)+' '+t('פריטים','items')+'</small></div><div class="dashboard-row-actions"><button type="button" class="button button-primary button-small" data-admin-gmach-open="'+esc(r.id)+'">'+t('כל הפרטים והפעולות','All details and actions')+'</button></div></article>'}
function changed(id){window.dispatchEvent(new CustomEvent('gmach:admin-updated',{detail:{id}}))}
async function open(id){
 let d=document.querySelector('#admin-gmach-details');if(!d){d=document.createElement('dialog');d.id='admin-gmach-details';d.className='modal modal-wide';document.body.append(d)}
 const close='<button class="dialog-close" type="button" aria-label="'+t('סגירה','Close')+'">×</button>';
 d.innerHTML=close+'<p>'+t('טוענים…','Loading…')+'</p>';d.querySelector('.dialog-close').onclick=()=>d.close();if(!d.open)d.showModal();
 try{
 const x=await api('/api/admin/organizations/'+encodeURIComponent(id)),r=x.organization;
 const field=(name,he,eng,value,type='text')=>'<label>'+t(he,eng)+'<input name="'+name+'" type="'+type+'" value="'+esc(value||'')+'"></label>';
 d.innerHTML=close+'<h2>'+original(r.name)+'</h2><p>'+t('מספר גמ״ח','Gmach number')+': '+esc(r.gmach_code??t('טרם הוקצה','Not assigned'))+'</p><p>'+original(r.owner_name)+' · '+esc(r.owner_email)+'</p><form class="form-grid" id="admin-gmach-form">'+field('name','שם','Name',r.name)+field('primaryCategory','תחום','Category',r.primary_category)+field('city','עיר','City',r.city)+field('neighborhood','שכונה','Neighborhood',r.neighborhood)+field('address','כתובת','Address',r.address)+field('phone','טלפון','Phone',r.contact_phone)+field('ownerEmail','אימייל בעלים (שינוי בעלות)','Owner email (change ownership)',r.owner_email)+field('serviceArea','אזור שירות','Service area',r.service_area)+'<label>'+t('תיאור','Description')+'<textarea name="description">'+esc(r.description)+'</textarea></label>'+hoursFields(r.hours_json)+'<label>'+t('סוג גמ״ח','Gmach type')+'<select name="organizationType">'+[['private','פרטי','Private'],['family','משפחתי','Family'],['community','קהילתי','Community'],['nonprofit','עמותה','Nonprofit'],['business','עסק','Business'],['authority','רשות','Authority']].map(a=>'<option value="'+a[0]+'" '+(r.organization_type===a[0]?'selected':'')+'>'+t(a[1],a[2])+'</option>').join('')+'</select></label><label>'+t('מצב אישור','Approval status')+'<select name="status">'+[['approved','מאושר','Approved'],['pending','ממתין','Pending'],['rejected','נדחה','Rejected']].map(a=>'<option value="'+a[0]+'" '+(r.status===a[0]?'selected':'')+'>'+t(a[1],a[2])+'</option>').join('')+'</select></label><label class="check"><input name="isHidden" type="checkbox" '+(r.is_hidden?'checked':'')+'>'+t('מוסתר מהציבור','Hidden from public')+'</label><label class="check"><input name="temporarilyClosed" type="checkbox" '+(r.temporarily_closed?'checked':'')+'>'+t('סגור זמנית','Temporarily closed')+'</label>'+field('reopensAt','פתיחה מחדש','Reopens at',r.reopens_at?localDate(r.reopens_at):'','datetime-local')+'<button class="button button-primary">'+t('שמירת פרטים ומצב','Save details and status')+'</button><p role="status" data-save-message></p></form><div class="dashboard-row-actions">'+[['branches','סניפים והרשאות גמ״ח','Branches and gmach permissions'],['advanced','כלים מתקדמים','Advanced tools'],['reviews','ביקורות ותגובות','Reviews and replies'],['add','הוספת פריט','Add item'],['delete','מחיקת הגמ״ח ופריטיו','Delete gmach and its items']].map(a=>'<button type="button" class="button '+(a[0]==='delete'?'button-danger':'button-secondary')+'" data-gmach-action="'+a[0]+'">'+t(a[1],a[2])+'</button>').join('')+'</div><details><summary>'+t('פרטים נוספים','Additional details')+'</summary><dl>'+Object.entries(r).filter(([k])=>!['owner_name','owner_email','name'].includes(k)).map(([k,v])=>'<dt>'+esc(k)+'</dt><dd dir="auto" style="overflow-wrap:anywhere">'+esc(v??'—')+'</dd>').join('')+'</dl></details><h3>'+t('פריטים ומספרים סידוריים','Items and serial numbers')+'</h3>'+x.items.map(i=>'<article class="dashboard-row"><div><strong>'+esc(i.title)+'</strong><p>'+t('מספר פריט','Item number')+': '+esc(i.item_code??'—')+' · '+esc(i.status)+' · '+Number(i.quantity)+' · '+esc(i.availability_status)+(i.deleted_at?' · '+t('נמחק','Deleted'):'')+'</p></div>'+(!i.deleted_at?'<button type="button" class="button button-secondary" data-gmach-item="'+esc(i.id)+'">'+t('מלאי','Inventory')+'</button><button type="button" class="button button-secondary" data-gmach-edit-item="'+esc(i.id)+'">'+t('עריכת פריט','Edit item')+'</button><button type="button" class="button button-secondary" data-gmach-units="'+esc(i.id)+'">'+t('יחידות ומספרים סידוריים','Units and serials')+'</button>':'')+'</article>').join('')+'<h3>'+t('השאלות (עד 200 האחרונות)','Loans (up to 200 latest)')+'</h3>'+x.loans.map(l=>'<article class="dashboard-row"><div><strong>'+esc(l.title)+'</strong><p>'+original(l.borrower_name)+' · '+esc(l.status)+' · '+esc(l.workflow_status||'')+'</p><small>'+esc(l.requested_from)+' — '+esc(l.requested_until)+'</small></div><button type="button" class="button button-secondary" data-gmach-loan="'+esc(l.id)+'">'+t('ציר זמן וניהול','Timeline and management')+'</button></article>').join('');
 d.querySelector('.dialog-close').onclick=()=>d.close();
 d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,msg=f.querySelector('[data-save-message]'),button=f.querySelector('button');button.disabled=true;try{const body=Object.fromEntries(new FormData(f));body.hours={};days.forEach((day,i)=>{const start=body['hoursStart'+i],end=body['hoursEnd'+i];if(start||end){if(!start||!end)throw new Error(t('יש למלא שעת התחלה וסיום','Enter both opening and closing times'));body.hours[day]=start+'–'+end}delete body['hoursStart'+i];delete body['hoursEnd'+i]});body.isHidden=f.elements.isHidden.checked;body.temporarilyClosed=f.elements.temporarilyClosed.checked;body.reopensAt=f.elements.reopensAt.value?new Date(f.elements.reopensAt.value).toISOString():null;await api('/api/admin/organizations/'+encodeURIComponent(id),{method:'PATCH',body});changed(id);await open(id)}catch(e){msg.textContent=e.message}finally{button.disabled=false}};
 d.querySelectorAll('[data-gmach-action]').forEach(b=>b.onclick=async()=>{try{const action=b.dataset.gmachAction;if(action==='delete'){if(!confirm(t('למחוק את הגמ״ח וכל פריטיו מהאתר?','Delete this gmach and all its items from the site?')))return;await api('/api/admin/entities/organizations/'+encodeURIComponent(id),{method:'DELETE'});d.close();changed(id);return}window.GmachAdminTools[action](id,r)}catch(e){alert(e.message)}});
 d.querySelectorAll('[data-gmach-item]').forEach(b=>b.onclick=()=>window.GmachAdminTools.item(b.dataset.gmachItem));
 d.querySelectorAll('[data-gmach-edit-item]').forEach(b=>b.onclick=()=>window.GmachAdminTools.editItem(x.items.find(i=>i.id===b.dataset.gmachEditItem),r));
 d.querySelectorAll('[data-gmach-units]').forEach(b=>b.onclick=()=>window.GmachAdminTools.units(b.dataset.gmachUnits));
 d.querySelectorAll('[data-gmach-loan]').forEach(b=>b.onclick=()=>window.GmachAdminLoan(b.dataset.gmachLoan));
 }catch(e){d.innerHTML=close+'<p role="alert">'+esc(e.message)+'</p>';d.querySelector('.dialog-close').onclick=()=>d.close()}
}
function localDate(v){const d=new Date(v);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-admin-gmach-open]');if(b){e.preventDefault();open(b.dataset.adminGmachOpen)}});
window.GmachAdmin={summary,open};
})();
